	CVisual* CVisual::Create(zar::CZAR& archive)
	{
		CVisual* visual = NULL;
		u32 vtype = 0;

		archive.Fetch("vtype", &vtype);

		switch (vtype)
		{
		case 2:
			visual = new CSubMesh();
		case 1:
			visual = new CMesh();
		case 0:
		case -1:
			visual = new CVisual();
		}

		if (visual)
			visual->Read(archive);

		return visual;
	}

